{
  "action": "guard_boundary",
  "target": "state 状态转移逻辑（S1/S2/S3 超时保护分支）",
  "params": {
    "condition": "step_cnt >= TIMEOUT",
    "next_state": "S_IDLE",
    "timeout_irq": "1'b1",
    "hold_cnt": "4'd0",
    "priority": "每个非空闲状态内最高优先级"
  },
  "rationale": "恢复被删除的超时保护分支，step_cnt 超阈值时强制回 IDLE 并产生 timeout_irq，避免边界回绕击穿 A8。"
}

{
  "action": "edit_assign",
  "target": "state (S_DATA 分支 bit_cnt==DATA_W-1 时的跳转目标)",
  "params": {
    "signal": "state",
    "old_value": "S_IDLE",
    "new_value": "S_STOP",
    "context": "S_DATA 状态下 bit_cnt == DATA_W - 1 时"
  },
  "rationale": "数据位最后一拍错误跳转到 S_IDLE，破坏了 DATA→STOP 的合法跳转并丢失停止位，应改回 S_STOP 以满足 A4 断言。"
}

{
  "action": "guard_boundary",
  "target": "count 的同步更新逻辑",
  "params": {
    "description": "在 always @(posedge clk or negedge rst_n) 的复位后分支中恢复 count 的增量守恒更新：count <= count + (can_wr ? 1'b1 : 1'b0) - (can_rd ? 1'b1 : 1'b0); 使同拍读写时 count 保持不变，仅写时 +1，仅读时 -1。"
  },
  "rationale": "count 更新逻辑被删除导致 A4 断言失败，需恢复同拍读写时 count 守恒的边界保护分支。"
}
